begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data)
select ('b4700000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'rights-'||i||'@example.test','{"full_name":"Rights Fixture"}'::jsonb from generate_series(1,5)i;
update public.profiles set role='admin' where id::text like 'b4700000%' and right(id::text,1) in ('3','4','5');
insert into public.admin_capabilities(profile_id,capability) values
('b4700000-0000-4000-8000-000000000003','support'),('b4700000-0000-4000-8000-000000000004','finance'),('b4700000-0000-4000-8000-000000000005','operations');
set local role anon;
select set_config('request.jwt.claim.role','anon',true);
select set_config('request.jwt.claim.sub','',true);
select is((select count(*)::integer from public.emergency_contacts where is_placeholder),5,'each local agency starts as a clearly marked placeholder');
select is((select count(*)::integer from public.emergency_contacts where phone is not null),1,'no invented local agency phone numbers');
select throws_ok($$select public.request_own_data_export(gen_random_uuid(),'en')$$,'42501',null,'anonymous users cannot request an account export');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000001',true);
create temp table requested_export as select public.request_own_data_export('b4710000-0000-4000-8000-000000000001','fil') id;
select is(public.request_own_data_export('b4710000-0000-4000-8000-000000000001','fil'),(select id from requested_export),'export request UUID is idempotent');
select is((select count(*)::integer from public.data_subject_request_audit where request_id=(select id from requested_export)),1,'request creates one audit row');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from public.data_subject_requests where id=(select id from requested_export)),0,'tourist B cannot see tourist A request');
select throws_ok($$select public.fulfil_data_subject_request((select id from requested_export))$$,'42501',null,'ordinary user cannot fulfil another export');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.fulfil_data_subject_request((select id from requested_export))$$,'42501',null,'finance alone cannot fulfil personal-data requests');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000003',true);
select lives_ok($$select public.fulfil_data_subject_request((select id from requested_export))$$,'support fulfils an own-data export');
select lives_ok($$select public.fulfil_data_subject_request((select id from requested_export))$$,'fulfilment retry is idempotent');
select is((select count(*)::integer from public.data_subject_exports where request_id=(select id from requested_export)),0,'support cannot directly download someone else export payload');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000001',true);
select is((select payload#>>'{profile,id}' from public.data_subject_exports where request_id=(select id from requested_export)),'b4700000-0000-4000-8000-000000000001','export contains requesting subject profile only');
select is((select status from public.data_subject_requests where id=(select id from requested_export)),'fulfilled','owner can see fulfilled state');
select is((select count(*)::integer from public.data_subject_request_audit where request_id=(select id from requested_export)),2,'one requested and one fulfilled audit event');
select throws_ok($$update public.data_subject_request_audit set action='account_deleted'$$,'42501',null,'client cannot rewrite data-rights audit');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from public.data_subject_exports),0,'cross-user export payload stays private');
select throws_ok($$select public.update_emergency_contact('pnp','1234567','PNP','PNP')$$,'42501',null,'ordinary user cannot publish emergency numbers');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000005',true);
select public.update_emergency_contact('pnp','1234567','Fixture PNP','Fixture PNP');
select is((select is_placeholder from public.emergency_contacts where id='pnp'),false,'operations can replace a placeholder with an explicitly verified fixture');
select is((select count(*)::integer from public.emergency_contact_audit where contact_id='pnp'),1,'contact change is audited');
select throws_ok($$select public.update_emergency_contact('pnp','tel:bad','PNP','PNP')$$,'P0001','Invalid contact details','URI injection cannot become a phone number');
select public.update_emergency_contact('pnp','','PNP','PNP');
select is((select phone is null and is_placeholder from public.emergency_contacts where id='pnp'),true,'clearing number restores a non-callable placeholder');
select lives_ok($$select public.get_operations_health()$$,'operations can inspect health metrics');
select set_config('request.jwt.claim.sub','b4700000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.get_operations_health()$$,'42501',null,'ordinary users cannot inspect operational metrics');
reset role;
select set_config('request.jwt.claim.role','service_role',true);
select public.prepare_account_deletion('b4700000-0000-4000-8000-000000000001','b4720000-0000-4000-8000-000000000001');
select is((select count(*)::integer from public.data_subject_exports where subject_id='b4700000-0000-4000-8000-000000000001'),0,'deletion erases prepared personal-data payloads');
select is((select status from public.data_subject_requests where subject_id='b4700000-0000-4000-8000-000000000001'),'cancelled','deletion closes requests without retaining export contents');
select is((select count(*)::integer from public.data_subject_request_audit where subject_id='b4700000-0000-4000-8000-000000000001'),3,'request lifecycle keeps append-only pseudonymous audit evidence');
insert into public.message_deliveries(recipient_id,channel,template_key,title,body,status,dedupe_key)
values('b4700000-0000-4000-8000-000000000002','push','fixture','Fixture','Fixture','failed','batch4-health-notification');
insert into cron.job_run_details(jobid,runid,status,start_time) select jobid,(select coalesce(max(runid),0)+10000 from cron.job_run_details),'failed',now() from cron.job limit 1;
select ok((public.collect_operations_health()->>'notification_failures')::integer>=1,'collector reports actual failed notification rows');
select ok((select value from public.operations_health where metric='cron_failures')>=1,'monitoring view reports actual pg_cron failures');
select ok(exists(select 1 from public.operational_alerts where dedupe_key='health:notification_failures' and severity='critical'),'notification failures raise critical operational alerts');
select ok(exists(select 1 from public.operational_alerts where dedupe_key='health:cron_failures' and severity='critical'),'cron failures raise critical operational alerts');
select * from finish();rollback;
